        oargs = sfn.fixupArgCount(args);

        if (oargs != null && argsMatchTypes(oargs, sfn.getDomain()) &&
            (best_sfn == null || preferredDeclaration(o.getFn(), sfn, best_decl, best_sfn))) {
            best_sfn = sfn;
            best_decl = o.getFn();
            best_generic = genericOf(o.getFn());
