    public static float numeralToFloat(java.math.BigInteger v, int r, int m) {
        if (v.signum() == 0) return 0.0f;
        java.math.BigInteger den = java.math.BigInteger.valueOf(r).pow(m);
        int lsb = lsbExponent(v, den, 24, -149);
